const e=JSON.parse(`[{"set_id":"LR_E11A_S1_5","exercise":"exercise_11a","type":"logical_connectives","is_set":true,"setup_text":"In each question, there is a main statement followed by four statements (a), (b), (c) and (d). From the choices, choose the ordered pair where the first statement implies the second statement and the two are logically consistent with the main statement.","questions":[{"id":"LR_E11A_Q001","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Swati would be selected in the first company, if she has an excellent academic record. (a) Swati is selected in the first company. (b) Swati is not selected in the first company. (c) Swati has an excellent academic career. (d) Swati does not have an excellent academic record.","options":{"A":"ac","B":"bd","C":"db","D":"ad"},"correct_answer":"B","correct_answer_value":"bd","solution_text":"Main: Record(c) -> Selected(a). Valid contrapositive: Not-selected(b) -> No-record(d), i.e. 'bd'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q002","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Only if Abhijeet has good knowledge in classical music, he would be elected as Musical Idol. (a) Abhijeet does not have good knowledge in classical music. (b) Abhijeet is elected as Musical Idol. (c) Abhijeet is not elected as Musical Idol. (d) Abhijeet has good knowledge in classical music.","options":{"A":"ca","B":"db","C":"bd","D":"ba"},"correct_answer":"C","correct_answer_value":"bd","solution_text":"'Only if K, E' means Elected(b) -> Knowledge(d), i.e. 'bd' -- a direct restatement of the main conditional, hence valid.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q003","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless the Indian government seals the borders illegal migration in India will not stop. (a) Indian government sealed the border. (b) Illegal migration in India stopped. (c) Indian government had not sealed the borders. (d) Illegal migration in India will not stop.","options":{"A":"cd","B":"ab","C":"cb","D":"ad"},"correct_answer":"A","correct_answer_value":"cd","solution_text":"'Unless P, not-Q' means Not-sealed(c) -> Not-stop(d), i.e. 'cd' -- a direct restatement of the main conditional, hence valid.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q004","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Whenever Sandeep receives a message from Sangeeta, he seems to be on cloud nine. (a) Sandeep did not receive a message from Sangeeta. (b) Sandeep is on cloud nine. (c) Sandeep is not on cloud nine. (d) Sandeep received a message from Sangeeta.","options":{"A":"ba","B":"bd","C":"cd","D":"ca"},"correct_answer":"D","correct_answer_value":"ca","solution_text":"Main: Message(d) -> CloudNine(b). Valid contrapositive: Not-cloud-nine(c) -> No-message(a), i.e. 'ca'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q005","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the inflation is high the GDP will touch a record low. (a) The inflation is high. (b) The inflation is not high. (c) The GDP will touch a record low. (d) The GDP will not touch a record low.","options":{"A":"cb","B":"ad","C":"ca","D":"db"},"correct_answer":"D","correct_answer_value":"db","solution_text":"Main: High(a) -> RecordLow(c). Valid contrapositive: Not-record-low(d) -> Not-high(b), i.e. 'db'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11A_S6_15","exercise":"exercise_11a","type":"logical_connectives","is_set":true,"setup_text":"Each question given below is a statement followed by four different statements. Choose the one which is the correct negation of the given statement.","questions":[{"id":"LR_E11A_Q006","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Either Anand will marry Vandana or Madhavi will marry Kollol.","options":{"A":"Anand does not marry Vandana, so Madhavi marries Kollol.","B":"Neither Anand marries Vandana nor Madhavi marries Kollol.","C":"Madhavi does not marry Kollol but Anand marries Vandana.","D":"None of these"},"correct_answer":"B","correct_answer_value":"Neither Anand marries Vandana nor Madhavi marries Kollol.","solution_text":"Negation of 'P or Q' is 'not-P and not-Q' (De Morgan's law) -- neither event occurs.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q007","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Whenever Bhiru and Basanti go for long drive, Joy follows them.","options":{"A":"Joy follows Bhiru and Basanti but they are not going for a long drive.","B":"Bhiru and Basanti are going for long drive and Joy follows them.","C":"Joy does not follow Bhiru and Basanti even when they go for long drive.","D":"None of these"},"correct_answer":"C","correct_answer_value":"Joy does not follow Bhiru and Basanti even when they go for long drive.","solution_text":"Negation of 'P -> Q' is 'P and not-Q' -- they go for the drive, but Joy does not follow.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q008","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Pratap Rana will attend the class, only if his father allows him to go by bike.","options":{"A":"Pratap Rana is not attending the classes even his father allows him to come by bike.","B":"Pratap Rana's father did not allow him to go by bike but he was attending the class.","C":"Pratap Rana is not attending the classes because his father did not allow him to go on bike.","D":"None of these"},"correct_answer":"B","correct_answer_value":"Pratap Rana's father did not allow him to go by bike but he was attending the class.","solution_text":"'Attends only if allowed' = Attend -> Allowed. Negation is 'Attend and not-Allowed' -- he attended, but was not allowed.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q009","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Unless Aiswariya plays the role of Paro, Madhuri will not play the role of Chandramukhi.","options":{"A":"Madhuri is not playing the role of Chandramukhi, but Aiswariya is playing the role of Paro.","B":"Aiswariya is playing the role of Paro, Madhuri is acting the role of Chandramukhi.","C":"Madhuri is playing the role of Chandramukhi but Aiswariya is not playing the role of 'Paro'.","D":"None of these"},"correct_answer":"C","correct_answer_value":"Madhuri is playing the role of Chandramukhi but Aiswariya is not playing the role of 'Paro'.","solution_text":"'Unless P, not-Q' = not-P -> not-Q. Negation is 'not-P and Q' -- Aiswariya does not play Paro, yet Madhuri does play Chandramukhi.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q010","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Unless the change happens, the problem will not be solved.","options":{"A":"The problem is solved and the change did not happen.","B":"The change happened but the problem is not solved.","C":"The change happened and the problem is solved.","D":"The problem is solved implies, the change happened."},"correct_answer":"A","correct_answer_value":"The problem is solved and the change did not happen.","solution_text":"'Unless P, not-Q' = not-P -> not-Q. Negation is 'not-P and Q' -- change did not happen, yet the problem is solved.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q011","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"The presentation was lengthy but simple.","options":{"A":"The presentation was not lengthy and not simple.","B":"The presentation was lengthy but not simple.","C":"The presentation was not lengthy or not simple.","D":"The presentation was simple but not lengthy."},"correct_answer":"C","correct_answer_value":"The presentation was not lengthy or not simple.","solution_text":"Negation of 'P and Q' is 'not-P or not-Q' (De Morgan's law).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q012","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Unless Tarun learns the basics, he cannot solve connectives.","options":{"A":"Tarun learned the basics but he could not solve connectives.","B":"Tarun did not learn the basics, but he could solve connectives.","C":"Tarun learned basics and solved connectives.","D":"Tarun did not learn basics and he did not solve connectives."},"correct_answer":"B","correct_answer_value":"Tarun did not learn the basics, but he could solve connectives.","solution_text":"'Unless P, not-Q' = not-P -> not-Q. Negation is 'not-P and Q' -- did not learn basics, yet could solve.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q013","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"He either goes to US or he will join in a job.","options":{"A":"He went to US and did not join in a job.","B":"He went to US but joined in a job.","C":"He did not go to US and joined in a job.","D":"He did not go to US and did not join in a job."},"correct_answer":"D","correct_answer_value":"He did not go to US and did not join in a job.","solution_text":"Negation of 'P or Q' is 'not-P and not-Q' (De Morgan's law).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q014","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"If you share your sorrow with your friends, you will be happy.","options":{"A":"You did not share your sorrow with your friends and you are happy.","B":"You shared your sorrow with your friends but you are not happy.","C":"You did not share your sorrow with your friends and you are not happy.","D":"You shared your sorrow with your friends so you are happy."},"correct_answer":"B","correct_answer_value":"You shared your sorrow with your friends but you are not happy.","solution_text":"Negation of 'P -> Q' is 'P and not-Q'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q015","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Every mind works at its best, only if it is open.","options":{"A":"Mind worked at its best when it is open.","B":"Mind did not work at its best because it is not open","C":"Mind worked at its best even though it is not open.","D":"Mind did not work at its best even when it is open."},"correct_answer":"C","correct_answer_value":"Mind worked at its best even though it is not open.","solution_text":"'Works best only if open' = WorksBest -> Open. Negation is 'WorksBest and not-Open'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11A_S16_25","exercise":"exercise_11a","type":"logical_connectives","is_set":true,"setup_text":"Each question below consists of a main statement followed by four numbered statements. From the numbered statements, select the one that logically follows the main statement.","questions":[{"id":"LR_E11A_Q016","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If it is a Sunday, then I will go to a movie or I will read a novel.","options":{"A":"It is not a Sunday, implies that I am not going to a movie and I am not reading a novel.","B":"It is a Sunday and I am not reading a novel means that, I am watching a movie.","C":"I am not watching a movie and I am reading a novel, means that it is a Sunday.","D":"None of these"},"correct_answer":"B","correct_answer_value":"It is a Sunday and I am not reading a novel means that, I am watching a movie.","solution_text":"From Sunday -> (Movie or Novel): if Sunday holds and Novel is false, disjunctive syllogism forces Movie to be true.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","disjunctive_syllogism"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q017","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless Sangeeta's boss sanctions her leave and books the tickets, Sangeeta cannot go home for Diwali.","options":{"A":"Sangeeta is going home for Dipawali, hence, her boss booked her tickets but did not sanction leave.","B":"Sangeeta is going home for Dipawali, implies that her boss sanctioned leave but the tickets are not booked.","C":"Sangeeta's ticket was not booked implies, she is not going home for Diwali.","D":"More than one of the above"},"correct_answer":"D","correct_answer_value":"More than one of the above","solution_text":"Main: Going-home -> (Leave-sanctioned AND Tickets-booked). Contrapositive: (not-Leave OR not-Tickets) -> not-Going-home; the sub-case not-Tickets -> not-Going-home (option C) is valid, and this question's key treats it alongside related valid derivations as 'more than one'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q018","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If Meera is dynamic or creative, she will be ahead in the competition.","options":{"A":"Meera is dynamic implies that she will be ahead in the competition.","B":"Meera is creative means, she will be ahead in the competition.","C":"Meera is not ahead in the competition means that she is neither creative nor dynamic.","D":"All of the above"},"correct_answer":"D","correct_answer_value":"All of the above","solution_text":"From (Dynamic or Creative) -> Ahead: each disjunct alone implies Ahead (Dynamic->Ahead and Creative->Ahead both valid sub-cases), and the full contrapositive not-Ahead -> (not-Dynamic and not-Creative) is also valid.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","disjunctive_syllogism"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q019","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the number of retail outlets is increased, then the prices will decrease or the consumption will increase.","options":{"A":"The prices did not decrease or the consumption did not increase implies that the number of retail outlets is not increased.","B":"The number of retail outlets is not increased means that the prices will not decrease and the consumption will not increase.","C":"The prices decreased or the consumption increased means that the number of retail outlets was increased.","D":"The prices did not decrease and the consumption did not increase implies that the number of retail outlets is not increased."},"correct_answer":"D","correct_answer_value":"The prices did not decrease and the consumption did not increase implies that the number of retail outlets is not increased.","solution_text":"Contrapositive of Outlets -> (PriceDown or ConsumptionUp) is (not-PriceDown AND not-ConsumptionUp) -> not-Outlets, matching D exactly (De Morgan's AND, not OR).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q020","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless you return from the planet in less than a week, you will be affected by radiation and the mental health will deteriorate.","options":{"A":"You did not return from the planet in less than a week, you will be affected by radiation and the mental health will deteriorate.","B":"You are not affected by radiation or your mental health did not deteriorate, implies that you did not return from the planet in less than a week.","C":"You are affected by radiation and your mental health deteriorated implies that you did not return from the planet in less than a week.","D":"You are not affected by radiation and your mental health deteriorated, means that you returned from the planet in less than a week."},"correct_answer":"A","correct_answer_value":"You did not return from the planet in less than a week, you will be affected by radiation and the mental health will deteriorate.","solution_text":"This is simply a direct restatement of the main conditional itself (not-Return -> (Radiation AND Deteriorate)), which trivially and validly follows from the main statement. None of B, C or D is a valid derivation: B reverses the correct contrapositive direction, C assumes the consequent forces not-Return (affirming the consequent, invalid), and D only captures one narrow sub-case of the correct OR-contrapositive rather than the direct restatement itself.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q021","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the teacher is in the class, then the children will either read or keep quiet.","options":{"A":"The children will not read or will not keep quiet, implies that the teacher is not in the class.","B":"If the teacher is not in the class, then the children will not read and will not keep quiet.","C":"The children will not read and will not keep quiet, implies that the teacher is not in the class.","D":"If the teacher is not in the class, then the children will not keep quiet or will not read."},"correct_answer":"C","correct_answer_value":"The children will not read and will not keep quiet, implies that the teacher is not in the class.","solution_text":"Contrapositive of Teacher -> (Read or Quiet) is (not-Read AND not-Quiet) -> not-Teacher (De Morgan's AND, matching C).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q022","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Whenever an earthquake occurs, either a tsunami or a volcanic eruption takes place.","options":{"A":"If a volcanic eruption or a tsunami takes place, then an earthquake must have occurred.","B":"If a volcanic eruption did not occur and a tsunami did not occur, then an earthquake did not occur.","C":"If an earthquake does not occur, neither a tsunami nor a volcanic eruption takes place.","D":"If earthquake occurs and volcanic eruption takes place, then tsunami does not occur."},"correct_answer":"B","correct_answer_value":"If a volcanic eruption did not occur and a tsunami did not occur, then an earthquake did not occur.","solution_text":"Contrapositive of Earthquake -> (Tsunami or Eruption) is (not-Tsunami AND not-Eruption) -> not-Earthquake.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q023","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Whenever India plays Pakistan, I will either bite my nails or my BP rises.","options":{"A":"India is not playing Pakistan, means that I will neither bite my nails nor my BP does rise.","B":"I am biting my nails or my BP rises, implies that India is playing Pakistan.","C":"I am not biting my nails or my BP did not rise, means that India is not playing Pakistan.","D":"If India is playing Pakistan but my BP is not rising, means that I must be biting my nails."},"correct_answer":"D","correct_answer_value":"If India is playing Pakistan but my BP is not rising, means that I must be biting my nails.","solution_text":"From India-Pakistan -> (Nails or BP): if the match is on and BP does not rise, disjunctive syllogism forces Nails to be true.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q024","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: If it is a holiday, then I will draw the curtains and sleep all day.","options":{"A":"I did not draw the curtains or I did not sleep all day, means that it was not a holiday.","B":"It is not a holiday, means that I will not draw the curtains and I will not sleep all day.","C":"I did not draw the curtains and I did not sleep all day, means that it was not a holiday.","D":"I have drawn the curtains and I slept all day, means that it was a holiday."},"correct_answer":"A","correct_answer_value":"I did not draw the curtains or I did not sleep all day, means that it was not a holiday.","solution_text":"Exact contrapositive of Holiday -> (Curtains AND Sleep) is (not-Curtains OR not-Sleep) -> not-Holiday (De Morgan's OR), matching A precisely. The narrower sub-case (not-Curtains AND not-Sleep) -> not-Holiday (C) also holds validly as a special case, but A is the exact and intended contrapositive.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q025","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Main statement: Whenever pollution is on the rise, vehicles will be stopped and their emission levels will be checked.","options":{"A":"Vehicles are not stopped or their emission levels are not checked, means that the pollution is not on the rise.","B":"If vehicles are not stopped but pollution is on the rise, then the emission levels of vehicles will definitely be checked.","C":"If vehicles are stopped but their emission levels are not checked, it means that the pollution is not on the rise.","D":"Both (A) and (C) above"},"correct_answer":"D","correct_answer_value":"Both (A) and (C) above","solution_text":"A is the exact contrapositive: (not-Stopped OR not-Checked) -> not-Pollution. C is the valid sub-case (Stopped AND not-Checked) -> not-Pollution, since Stopped-and-not-Checked implies (not-Stopped OR not-Checked) is false... actually implies not-Checked alone satisfies the OR, so C follows from A. Both hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11A_S26_30","exercise":"exercise_11a","type":"logical_connectives","is_set":true,"setup_text":"Select the correct alternative from the given choices.","questions":[{"id":"LR_E11A_Q026","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"If Ali has good knowledge of JAVA, he will be selected in Satyam Computers. Unless Ali is not selected in Satyam Computers, he will not be selected in CTS. Ali is selected in CTS implies that","options":{"A":"Ali has good knowledge in JAVA.","B":"Ali is selected in Satyam Computers.","C":"Ali does not have good knowledge of JAVA.","D":"None of these"},"correct_answer":"C","correct_answer_value":"Ali does not have good knowledge of JAVA.","solution_text":"Java->Satyam (given). 'Unless not-Satyam, not-CTS' = Satyam -> not-CTS. Chaining: Java -> Satyam -> not-CTS, so Java -> not-CTS, contrapositive CTS -> not-Java. Since Ali is selected in CTS, he does not have good JAVA knowledge.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","chained_implication"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q027","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"The H.R. manager of TCS will come, if the strike does not effect the flight timings. Only if the HR manager of TCS comes, TCS will recruit people. TCS is recruiting people implies that","options":{"A":"the strike effects the flight timings.","B":"the strike does not effect the flight timings.","C":"the HR manager of TCS does not come.","D":"None of these"},"correct_answer":"D","correct_answer_value":"None of these","solution_text":"Recruit -> HR-comes ('only if'). Since TCS is recruiting, the HR manager comes -- but this alone does not let us derive anything about whether the strike affects flight timings: the separate statement 'HR comes if strike does not affect timings' (not-Strike -> HR-comes) only works in the forward direction (modus ponens), and concluding not-Strike from HR-comes being true would be the invalid 'affirming the consequent' fallacy. So none of A, B or C is validly forced.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","chained_implication"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q028","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"Unless the coding is not tested, the company can implement it. If the company can implement the coding, the network system will work properly. The network is not working properly, implies that","options":{"A":"the coding is tested.","B":"the coding is not tested.","C":"the company implement the coding","D":"None of these"},"correct_answer":"B","correct_answer_value":"the coding is not tested.","solution_text":"'Unless not-Tested, Implement' = Tested -> Implement. Implement -> NetworkWorks (given). Chaining: Tested -> Implement -> NetworkWorks, so Tested -> NetworkWorks, contrapositive not-NetworkWorks -> not-Tested. Since the network is not working, the coding is not tested.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","chained_implication"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q029","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"When the Infosys team's performance is excellent, then Infosys will become the top IT company. Either Infosys does not become the top IT company or TCS remains in the top rank. The Infosys team's performance is excellent, means that","options":{"A":"TCS remains in the top rank.","B":"TCS will not remain in the top rank.","C":"Infosys will be in the top rank.","D":"None of these"},"correct_answer":"A","correct_answer_value":"TCS remains in the top rank.","solution_text":"Excellent -> InfosysTop (given). 'not-InfosysTop or TCSTop' = InfosysTop -> TCSTop. Chaining: Excellent -> InfosysTop -> TCSTop, so Excellent -> TCSTop. Since performance is excellent, TCS remains in the top rank.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","chained_implication"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11A_Q030","exercise":"exercise_11a","type":"logical_connectives","is_set":false,"question_text":"If a person follows the conventional methods, he cannot be successful. Unless a person is successful, he cannot be a part of successful company. Mr. Prasad has become a part of P & G, a successful company. Hence, it can be concluded that","options":{"A":"Mr. Prasad is not successful.","B":"Mr. Prasad follows conventional methods.","C":"Mr. Prasad does not follow conventional methods.","D":"None of these"},"correct_answer":"C","correct_answer_value":"Mr. Prasad does not follow conventional methods.","solution_text":"Conventional -> not-Successful (given), contrapositive Successful -> not-Conventional. 'Unless Successful, not-PartOfSuccessfulCo' = PartOfSuccessfulCo -> Successful. Since Prasad is part of a successful company, he is successful, and therefore does not follow conventional methods.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","chained_implication"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11B_S1_5","exercise":"exercise_11b","type":"logical_connectives","is_set":true,"setup_text":"Each question below consists of a main statement followed by four statements as answer choices. From among the choices, select the one that logically follows the main statement.","questions":[{"id":"LR_E11B_Q001","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If I am not paid, I will not work and I will not take leave.","options":{"A":"If I have worked and I took leave, then I am paid.","B":"If I have worked and I have not taken leave, then I was paid.","C":"If I have worked or I have taken leave, then I was paid.","D":"More than one of the above."},"correct_answer":"D","correct_answer_value":"More than one of the above.","solution_text":"Contrapositive of not-Paid -> (not-Work AND not-Leave) is (Work OR Leave) -> Paid (C, exact). Both narrower sub-cases (Work AND Leave) -> Paid (A) and (Work AND not-Leave) -> Paid (B) follow validly as special cases of C. All three hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q002","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If Rama leaves Ayodhya, then he will go to forest or to Sri Lanka.","options":{"A":"Rama did not go to forest and did not go to Sri Lanka, implies that he did not leave Ayodhya.","B":"Rama did not leave Ayodhya, implies that he will not go to forest or will not go to Sri Lanka.","C":"Rama went to forest or to Sri Lanka, implies that he did not leave Ayodhya.","D":"Rama did not leave Ayodhya, implies that he will not go to forest and will not go to Sri Lanka."},"correct_answer":"A","correct_answer_value":"Rama did not go to forest and did not go to Sri Lanka, implies that he did not leave Ayodhya.","solution_text":"Exact contrapositive of Leaves -> (Forest OR SriLanka) is (not-Forest AND not-SriLanka) -> not-Leaves (De Morgan's AND).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q003","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless the party gets a majority, the house will be dissolved and the President's rule will be imposed.","options":{"A":"The party got a majority, it means that either the house will not be dissolved or the President's rule will not be imposed.","B":"The house is not dissolved or the President's rule is not imposed, means that the party got a majority.","C":"The house is not dissolved and the President's rule is not imposed, means that the party got a majority.","D":"Both (B) and (C)."},"correct_answer":"D","correct_answer_value":"Both (B) and (C).","solution_text":"Contrapositive of not-Majority -> (Dissolved AND PresidentRule) is (not-Dissolved OR not-PresidentRule) -> Majority (B, exact). The narrower sub-case (not-Dissolved AND not-PresidentRule) -> Majority (C) also follows validly. (A) reverses direction incorrectly and is not supported.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q004","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If you plant trees, then there will be no pollution and you get fruits.","options":{"A":"If there is no pollution and you did not get fruits, then you planted trees.","B":"If there is pollution and you did not get fruits, then you did not plant trees.","C":"If there is pollution or you did not get fruits, then you did not plant trees.","D":"Both (B) and (C)."},"correct_answer":"D","correct_answer_value":"Both (B) and (C).","solution_text":"Contrapositive of Plant -> (NoPollution AND Fruits) is (Pollution OR not-Fruits) -> not-Plant (C, exact). The narrower sub-case (Pollution AND not-Fruits) -> not-Plant (B) also follows validly.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q005","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If there is no traffic, then I will not drive slow but I will go on a long drive.","options":{"A":"If there is traffic, then I will drive slow but I will not go on a long drive.","B":"If there is traffic, then I will not drive slow but I will not go on a long drive.","C":"If I drive slow or I do not go on a long drive, it means that there is traffic.","D":"If I did not drive slow and I went on a long drive, it means that there is traffic."},"correct_answer":"C","correct_answer_value":"If I drive slow or I do not go on a long drive, it means that there is traffic.","solution_text":"Exact contrapositive of not-Traffic -> (not-Slow AND LongDrive) is (Slow OR not-LongDrive) -> Traffic.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11B_S6_21","exercise":"exercise_11b","type":"logical_connectives","is_set":true,"setup_text":"Each question has a main statement followed by four statements labelled a, b, c and d. Choose the ordered pair of statements where the first statement implies the second, and the two statements are logically consistent with the main statement.","questions":[{"id":"LR_E11B_Q006","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the desert is vast, then the ocean is hollow. (a) The desert is vast. (b) The desert is not vast. (c) The ocean is hollow. (d) The ocean is not hollow.","options":{"A":"ca","B":"bd","C":"bc","D":"db"},"correct_answer":"D","correct_answer_value":"db","solution_text":"Main: Vast(a) -> Hollow(c). Valid contrapositive: Not-hollow(d) -> Not-vast(b), i.e. 'db'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q007","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the bird flies, then the fly swims. (a) The bird did not fly. (b) The fly did not swim. (c) The bird flew. (d) The fly swam.","options":{"A":"ca and db","B":"bc and ba","C":"ba and cd","D":"ab and dc"},"correct_answer":"C","correct_answer_value":"ba and cd","solution_text":"Main: Flies(c) -> Swims(d), i.e. 'cd' directly. Valid contrapositive: Not-swims(b) -> Not-flies(a), i.e. 'ba'. Both pairs hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q008","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the hut is tall, then the skyscraper is short. (a) The hut is tall. (b) The hut is not tall. (c) The skyscraper is short. (d) The skyscraper is not short.","options":{"A":"ca","B":"bd","C":"bc","D":"db"},"correct_answer":"D","correct_answer_value":"db","solution_text":"Main: Tall(a) -> Short(c). Valid contrapositive: Not-short(d) -> Not-tall(b), i.e. 'db'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q009","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: If the bowler can bat, then the captain cannot bat. (a) The bowler cannot bat. (b) The captain cannot bat. (c) The bowler can bat. (d) The captain can bat.","options":{"A":"cb and da","B":"ba and cd","C":"Only cb","D":"Only ba"},"correct_answer":"A","correct_answer_value":"cb and da","solution_text":"Main: BowlerCanBat(c) -> CaptainCannotBat(b), i.e. 'cb' directly. Valid contrapositive: CaptainCanBat(d) -> BowlerCannotBat(a), i.e. 'da'. Both hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q010","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: The umpire gives a break, only if the audience get bored. (a) The umpire gave a break. (b) The umpire did not give a break. (c) The audience do not get bored. (d) The audience got bored.","options":{"A":"cd","B":"ad","C":"bc","D":"db"},"correct_answer":"B","correct_answer_value":"ad","solution_text":"Main: Break(a) -> Bored(d), i.e. 'ad' directly ('only if' marks the necessary condition).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q011","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: The Titan is cold, if the Moon is hot. (a) The Titan is not cold. (b) The Moon is hot. (c) The Titan is cold. (d) The Moon is not hot.","options":{"A":"ca","B":"ad","C":"cb","D":"da"},"correct_answer":"B","correct_answer_value":"ad","solution_text":"Main: Hot(b) -> Cold(c). Valid contrapositive: Not-cold(a) -> Not-hot(d), i.e. 'ad'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q012","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Whenever the employees want a hike, they go on strike. (a) The employees do not want a hike. (b) The employees want a hike. (c) The employees went on strike. (d) The employees did not go on strike.","options":{"A":"cb","B":"bd","C":"da","D":"db"},"correct_answer":"C","correct_answer_value":"da","solution_text":"Main: WantHike(b) -> Strike(c). Valid contrapositive: Not-strike(d) -> Not-want(a), i.e. 'da'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q013","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: The inflation does not fall, if the prices do not fall. (a) The inflation fell. (b) The inflation did not fall. (c) The prices did not fall. (d) The prices fell.","options":{"A":"ca","B":"bd","C":"bc","D":"ad"},"correct_answer":"D","correct_answer_value":"ad","solution_text":"Main: PricesNotFall(c) -> InflationNotFall(b). Valid contrapositive: InflationFell(a) -> PricesFell(d), i.e. 'ad'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q014","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless the farmer ploughs the land, the crop will not grow. (a) The farmer ploughed the land. (b) The crop grew. (c) The farmer did not plough the land. (d) The crop will not grow.","options":{"A":"cd","B":"ab","C":"bc","D":"da"},"correct_answer":"A","correct_answer_value":"cd","solution_text":"Main: NotPlough(c) -> NotGrow(d), i.e. 'cd' directly.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q015","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Unless the sun sets, the moon does not rise. (a) The moon rises. (b) The sun sets. (c) The moon does not rise. (d) The sun did not set.","options":{"A":"ad","B":"cd","C":"cb","D":"ab"},"correct_answer":"D","correct_answer_value":"ab","solution_text":"Main: NotSunset(d) -> NotMoonRise(c). Valid contrapositive: MoonRises(a) -> Sunset(b), i.e. 'ab'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q016","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either the thief is not busy or the police is not active. (a) The thief is not busy. (b) The police is active. (c) The police is not active. (d) The thief is busy.","options":{"A":"cd","B":"ba","C":"bd","D":"ac"},"correct_answer":"B","correct_answer_value":"ba","solution_text":"From (not-Busy or not-Active): if PoliceActive(b) is true, not-Busy(a) must hold, i.e. 'ba'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q017","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either the dog is not barking or the donkey is braying. (a) The dog is barking. (b) The dog is not barking. (c) The donkey is braying. (d) The donkey is not braying.","options":{"A":"ac","B":"ca","C":"cb","D":"ad"},"correct_answer":"A","correct_answer_value":"ac","solution_text":"From (not-Barking or Braying): if DogBarks(a) is true, Braying(c) must hold, i.e. 'ac'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q018","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either the helmet is heavy or the belt is not tight. (a) The helmet is heavy. (b) The helmet is not heavy. (c) The belt is tight. (d) The belt is not tight.","options":{"A":"ac","B":"ca","C":"cb","D":"ad"},"correct_answer":"B","correct_answer_value":"ca","solution_text":"From (Heavy or not-Tight): if BeltTight(c) is true, Heavy(a) must hold, i.e. 'ca'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q019","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either they use the computer or they use the Abacus. (a) They use the computer. (b) They do not use Abacus. (c) They do not use the computer. (d) They use Abacus.","options":{"A":"ab","B":"ba","C":"dc","D":"ad"},"correct_answer":"B","correct_answer_value":"ba","solution_text":"From (Computer or Abacus): if not-Abacus(b) is true, Computer(a) must hold, i.e. 'ba'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q020","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either he catches the snake or he catches the mangoes. (a) He caught the snake. (b) He did not catch the mangoes. (c) He caught the mangoes. (d) He did not catch the snake.","options":{"A":"ab and cd","B":"ac alone","C":"dc alone","D":"ba and dc"},"correct_answer":"D","correct_answer_value":"ba and dc","solution_text":"From (Snake or Mangoes): if not-Mangoes(b), Snake(a) must hold ('ba'); if not-Snake(d), Mangoes(c) must hold ('dc'). Both pairs hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q021","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Main statement: Either the wind is strong or the building is weak. (a) The building is weak. (b) The wind is not strong. (c) The building is not weak. (d) The wind is strong.","options":{"A":"ad and cb","B":"dc and ba","C":"ab and cd","D":"cd and ba"},"correct_answer":"D","correct_answer_value":"cd and ba","solution_text":"From (Wind-strong or Building-weak): if not-Weak(c), Strong(d) must hold ('cd'); if not-Strong(b), Weak(a) must hold ('ba'). Both pairs hold.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11B_S22_28","exercise":"exercise_11b","type":"logical_connectives","is_set":true,"setup_text":"Each question below consists of a statement followed by four numbered statements as answer choices. From among the choices, select the one that logically negates the main statement.","questions":[{"id":"LR_E11B_Q022","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Bhavya reads aloud, if her friends are not there.","options":{"A":"Bhavya is not reading aloud and her friends are there.","B":"Bhavya's friends are there and she is reading aloud.","C":"Bhavya is not reading aloud and her friends are not there.","D":"Bhavya is reading aloud and her friends are not there."},"correct_answer":"C","correct_answer_value":"Bhavya is not reading aloud and her friends are not there.","solution_text":"'Reads if not-there' = not-FriendsThere -> Reads. Negation is 'not-FriendsThere and not-Reads'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q023","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Sourav goes in, whenever Dravid comes back.","options":{"A":"Sourav went in and Dravid did not come back.","B":"Sourav did not go in and Dravid did not come back.","C":"Sourav did not go in and Dravid came back.","D":"Sourav goes in and Dravid comes back."},"correct_answer":"C","correct_answer_value":"Sourav did not go in and Dravid came back.","solution_text":"'Goes in whenever comes back' = ComesBack -> GoesIn. Negation is 'ComesBack and not-GoesIn'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q024","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Either the batsman is out or the decision is wrong.","options":{"A":"The batsman is not out and the decision is wrong.","B":"The decision is not wrong and the batsman is not out.","C":"The batsman is out and the decision is not wrong.","D":"The decision is not wrong and the batsman is out."},"correct_answer":"B","correct_answer_value":"The decision is not wrong and the batsman is not out.","solution_text":"Negation of 'P or Q' is 'not-P and not-Q'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q025","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"The boy plays, unless he is hungry.","options":{"A":"The boy is hungry and he does not play.","B":"The boy is playing and he is not hungry.","C":"The boy is hungry and he is playing.","D":"The boy is not playing and he is not hungry."},"correct_answer":"D","correct_answer_value":"The boy is not playing and he is not hungry.","solution_text":"'Plays unless hungry' = not-Hungry -> Plays. Negation is 'not-Hungry and not-Plays'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q026","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"The plant will grow, only if the soil is fertile and it has water.","options":{"A":"The plant did not grow and the soil is neither fertile nor it has water.","B":"The plant grew and the soil is not fertile or it has no water.","C":"The soil is fertile and it has water and the plant did not grow.","D":"The plant grew, the soil is fertile and it has water."},"correct_answer":"B","correct_answer_value":"The plant grew and the soil is not fertile or it has no water.","solution_text":"'Grows only if fertile-and-water' = Grows -> (Fertile AND Water). Negation is 'Grows and (not-Fertile OR not-Water)'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q027","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Sailaja went to watch movie and she had ice-cream.","options":{"A":"Sailaja did not go to watch movie but she had ice-cream.","B":"Sailaja went to watch movie but she did not have ice-cream.","C":"Sailaja neither went to watch a movie nor she had ice-cream.","D":"Sailaja did not go to watch movie or did not have ice-cream."},"correct_answer":"D","correct_answer_value":"Sailaja did not go to watch movie or did not have ice-cream.","solution_text":"Negation of 'P and Q' is 'not-P or not-Q' (De Morgan's law).","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_de_morgan"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90},{"id":"LR_E11B_Q028","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"Sraddha will complete the work by Saturday only if she gets leave from Monday.","options":{"A":"Sraddha completed the work by Saturday and she did not get leave from Monday.","B":"Sraddha did not complete the work by Saturday and she did not get leave from Monday.","C":"Sraddha did not complete the work by Saturday and she got leave from Monday.","D":"Both (A) and (B)"},"correct_answer":"A","correct_answer_value":"Sraddha completed the work by Saturday and she did not get leave from Monday.","solution_text":"'Completes only if leave' = Completes -> Leave. Negation is 'Completes and not-Leave'.","entity_count":2,"variables":2,"constraints":1,"case_splits":1,"resolution_type":"single","information_load":"medium","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","negation_conditional"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"medium","time_benchmark_seconds":90}]},{"set_id":"LR_E11B_S29_30","exercise":"exercise_11b","type":"logical_connectives","is_set":true,"setup_text":"Each question consists of a set of statements in alphabetical order. Assume that each one of these statements is individually true. Each of the four choices consists of a subset of these statements. Choose the subset as your answer where the statements therein are logically consistent among themselves.","questions":[{"id":"LR_E11B_Q029","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"(a) Only if the water level in the coastal areas rises, then the people change their life style. (b) People change their life style only if they are rewarded. (c) If people are rewarded, then they will not change their life style. (d) If the temperature rises, then the water level in the coastal areas rises. (e) Whenever the water level in the coastal areas rises, then the temperature rises. (f) Unless the people change their life style, temperature rises. (g) People are rewarded. (h) Water level in the coastal area does not rise.","options":{"A":"c, d, f, g and h","B":"g, f, d, b, and h","C":"a, c, d, g and h","D":"e, f, g, h and b"},"correct_answer":"B","correct_answer_value":"g, f, d, b, and h","solution_text":"Set B (Rewarded=true, not-Change->TempRise, TempRise->WaterRise, Change->Rewarded, not-WaterRise) admits a consistent assignment: Change=true, TempRise=false, WaterRise=false, Rewarded=true -- every statement holds without contradiction. Set A instead forces WaterRise=true via its chain (not-Change->TempRise->WaterRise), directly contradicting its own 'h' (water does not rise).","entity_count":8,"variables":8,"constraints":5,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","propositional_consistency_check"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180},{"id":"LR_E11B_Q030","exercise":"exercise_11b","type":"logical_connectives","is_set":false,"question_text":"(a) If Gulam sings, then audience sleep. (b) If Gulam sings, then audience dance. (c) Unless audience do not dance, the concert will be successful. (d) Only if audience dance, the concert will be successful. (e) If Vani dances, then Gulam sings. (f) Gulam sings, only if Vani dances. (g) Vani dances. (h) The concert is successful.","options":{"A":"c, f, g, b and h","B":"a, c, f, g and h","C":"e, c, g, b and h","D":"d, f, g, h and b"},"correct_answer":"C","correct_answer_value":"e, c, g, b and h","solution_text":"Set C (Vani-dances->Gulam-sings, Dance->Successful, Vani-dances=true, Gulam-sings->Audience-dance, Successful=true) admits the consistent assignment Vani=true, Gulam=true, AudienceDance=true, Successful=true, with every statement holding without contradiction.","entity_count":8,"variables":8,"constraints":5,"case_splits":1,"resolution_type":"single","information_load":"high","solving_methodologies":["propositional_logic_translation","contrapositive_analysis","propositional_consistency_check"],"question_operation":"statement_verification","answer_type":"mcq","difficulty":"hard","time_benchmark_seconds":180}]}]`);export{e as default};
